html.script:
(blockcontext, pageContext, item) => {
    let eventType = item.eventType;
    if (eventType === "INCIDENT_ACCEPTED_AS_MAJOR_INCIDENT") {
        return '<now-icon icon="fire-fill" style="color: #C83C36;" size="md"></now-icon>';
    }
    if (eventType === "INCIDENT_RESOLVED") {
        return '<now-icon icon="circle-check-fill" style="color: #33830B;" size="md"></now-icon>';
    } 
    if (eventType === "INCIDENT_CREATED") {
        return '<now-icon icon="circle-record-fill" size="md" style="color: #4F52BD; fill: CECFED;"></now-icon>';
    }
    if (eventType === "INCIDENT_CLOSED" || eventType === "INCIDENT_TASK_CREATED" || eventType === "INCIDENT_TASK_CLOSED") {
        return iconText = '<now-icon icon="circle-fill" style="color: #CECFED;" size="md"></now-icon>';
    }
    return '<now-icon icon="comment-fill" style="color: #4F52BD;" size="md"></now-icon>';
}
